return "#获取基础信息\nget_swim_info 30001 {\n    response {\n        .team {\n            id \t  0 : integer\n            score 1 : integer\n            rank  2 : integer\n            buff  3 : integer\n            ranklist 4 : *integer # 历史排名\n        }\n        result 0 : integer\n        teams  1 : *team   # 最新队伍信息\n        match  2 : integer # 已完成场次 初始0\n    }\n}\n\n#投票\nswim_vote 30002 {\n    request {\n        type 0 : integer # 1 场 2 轮\n        num 1 : integer #指定场次投票\n        ranklist 3 : *integer #队伍id排序\n    }\n    response {\n        result 0 : integer# 1 成功 2 不在应援时间 3 该场次不可应援 4 该周不可应援\n    }\n}\n\n#获取指定场次比赛\nget_specific_swim_match 30003 {\n    request {\n        match 0 : integer #场次\n    }\n    response {\n        .team {\n            id 0 : integer\n            rank 1 : integer\n            buff 2 : integer\n            player 3 : string\n        }\n        result 0 : integer# 1 成功 2 活动未开放 3 比赛未开始 4 比赛数据有误\n        trackid 1 : integer #赛道id\n        teams 2 : *team\n        ranklist 3 : *integer #投票\n    }\n}\n\n#查看投票奖励\ncheck_swim_vote_reward 30004 {\n    response {\n        .reward {\n            type 0 : integer # 1 场 2 轮\n            num 1 : integer #计数 场次/轮次\n        }\n        result 0 : integer # 1 成功\n        rewards 1 : *reward\n    }\n}\n\n#领取投票奖励\nget_swim_vote_reward 30005 {\n    request {\n        type 0 : integer  # 1 场 2 轮\n        num  1 : integer # 场次/轮次\n    }\n    response {\n        result 0 : integer # 1 成功 2 未参与应援 3 奖励已领取 4 未到结算时间 5 配置错误\n        gold    1 : integer\n        diamond 2 : integer\n        items   3 : *item\n        reward  4 : integer  #1 优胜  2 达成\n    }\n}\n\n#获取投票信息\nget_swim_vote_info 30006 {\n    request {\n        type 0 : integer  # 1 场 2 轮\n    }\n    response {\n        result 0 : integer # 1 成功 2 未在活动时间\n        type 1 : integer # 1 场 2 轮\n        num 2 : integer # 场次/轮次\n        rates 3 : *integer #支持率 索引对应队伍id\n        ranklist 4 : *integer #投票\n    }\n}\n\n# 获取投票记录\nget_swim_record 30007 {\n    response {\n        .swim_data {\n            id   0 : integer\n            vote 1 : integer # 1 优胜  2 达成 3 未投票\n        }\n        result 0 : integer\n        data    1 : *swim_data\n    }\n}\n\n# 获取指定轮排名\nget_swim_round_rank 30008 {\n    request {\n        round 0 : integer\n    }\n    response {\n        result 0 : integer\n        ranklist 1 : *integer \n    }\n}\n\n"
